use rei_microphysics::{axbi_driver::{Driver,DriverConfig,DriverState,SourceClockConfig,SourcePlacement,NativeClockMode,PhysicalBirthRule},axbi_covariant_transport::{PhotonAttenuation,PhotonState},igm_state::{IgmGasState,w_erg_per_h_to_ev},HHeModel,Absorber,AtomicProvider,ForwardError};
fn initial(seed:bool)->(Driver,DriverState,f64){let mut c=DriverConfig::baseline();c.transport_cells=16;c.transport_threads=1;c.background_panels=128;let(mut d,mut s)=Driver::new(c).unwrap();let nh=d.n_h0_cm3/s.a.powi(3);let nhe=d.n_he0_cm3/s.a.powi(3);s.gas=IgmGasState::from_temperature([0.075,0.12,0.03],nh,nhe,15000.).unwrap();let g=d.geometry_point(s.a).unwrap().geometry().unwrap();if seed{let mut p=d.transport.empty_state();let l=d.transport.inject(&mut p,&g,20.,1e16).unwrap();s.photons=p.number;s.photon_energy_ref=p.energy_ref;s.photon_support_lo=p.support_lo;s.photon_support_hi=p.support_hi;s.ledgers.source_n=l.added_photons_per_h;s.ledgers.source_u=l.added_energy_ev_per_h;}d.set_source_clocks(&s,options()).unwrap();let ap=AtomicProvider::reference();let abs=[nh*0.925,nhe*0.85,nhe*0.12];let rate=HHeModel::controlled_fixture().c_cm_s*(0..3).map(|j|abs[j]*ap.cross_section([Absorber::HI,Absorber::HeI,Absorber::HeII][j],20.).unwrap()).sum::<f64>();(d,s,rate)}
fn options()->SourceClockConfig{SourceClockConfig{microphysics:NativeClockMode::AllMid,opacity_midpoint:true,source:SourcePlacement::Disabled,attenuation:PhotonAttenuation::Exponential,nonlinear_tolerance:1e-15}}
fn binding(d:&Driver,s:&DriverState)->f64{let t=HHeModel::controlled_fixture().threshold_ev;let[x,y,z]=s.gas.fractions;t[0]*x+d.n_he0_cm3/d.n_h0_cm3*(t[1]*(y+z)+t[2]*z)}
fn same(a:&DriverState,b:&DriverState){assert_eq!(a.a,b.a);assert_eq!(a.gas.fractions,b.gas.fractions);assert_eq!(a.gas.w_erg_per_h,b.gas.w_erg_per_h);assert_eq!(a.photons,b.photons);assert_eq!(a.photon_energy_ref,b.photon_energy_ref);assert_eq!(a.photon_support_lo,b.photon_support_lo);assert_eq!(a.photon_support_hi,b.photon_support_hi);assert_eq!(format!("{:?}",a.ledgers),format!("{:?}",b.ledgers));}
#[test]fn explicit_clock_and_serial_jacobian_guards(){let(mut d,mut s,k)=initial(true);for opt in [SourceClockConfig{microphysics:NativeClockMode::OwnerBe,..options()},SourceClockConfig{opacity_midpoint:false,..options()},SourceClockConfig{source:SourcePlacement::Before,..options()}]{d.set_source_clocks(&s,opt).unwrap();let mut n=0;assert!(matches!(d.chemical_stage_ssprk2(&mut s,0.01/k,&mut n),Err(ForwardError::InvalidInput("AXBI_SSP_CLOCK_PRECONDITION"))));assert_eq!(n,0);}d.set_source_clocks(&s,options()).unwrap();d.config.parallel_jacobian_columns=true;let mut n=0;assert!(d.chemical_stage_ssprk2(&mut s,0.01/k,&mut n).is_err());}
#[test]fn seeded_coupled_stage_conserves_independent_energy_and_events(){let(d,mut s,k)=initial(true);let b=s.clone();let w0=w_erg_per_h_to_ev(b.gas.w_erg_per_h).unwrap();let bind0=binding(&d,&b);let(n0,u0)=d.photon_inventory(&b);let mut n=0;let r=d.chemical_stage_ssprk2(&mut s,0.1/k,&mut n).unwrap();let(n1,u1)=d.photon_inventory(&s);let e=w_erg_per_h_to_ev(s.gas.w_erg_per_h).unwrap()-w0+binding(&d,&s)-bind0+u1-u0+s.ledgers.escaped_u-s.ledgers.cmb_input;assert!(e.abs()<1e-10*b.ledgers.source_u.max(1.),"raw energy {e}");assert!((n0-n1-r.transport.absorption.absorbed_per_h.iter().sum::<f64>()).abs()<1e-10);assert_ne!(s.gas.fractions,b.gas.fractions);assert!(r.rhs.photo_events_cm3_s.iter().sum::<f64>()>0.);assert!(n>1);}
#[test]fn deliberate_cfl_macro_failure_rolls_back_but_charges_work(){let(d,mut s,k)=initial(true);let mut n=0;d.chemical_stage_ssprk2(&mut s,0.01/k,&mut n).unwrap();s.rhs_evaluations=n;let b=s.clone();let rhs=format!("{:?}",d.last_clock_rhs().unwrap());let error=d.fixed_step_physical_birth_ssprk2(&mut s,0.005,PhysicalBirthRule::DisabledGauss2).unwrap_err();assert!(matches!(error,ForwardError::InvalidInput("AXBI_SSP_CFL")),"{error:?}");same(&s,&b);assert_eq!(s.attempts,b.attempts+1);assert!(s.rhs_evaluations>b.rhs_evaluations);assert_eq!(format!("{:?}",d.last_clock_rhs().unwrap()),rhs);}
#[test]fn gauss_birth_nodes_weights_and_actual_microsegment_ledgers(){let(d,mut s,_)=initial(false);let b=s.clone();let dx=1e-5/32.;let r=d.fixed_step_physical_birth_ssprk2(&mut s,dx,PhysicalBirthRule::Gauss2).unwrap();assert_eq!(r.birth.births.len(),2);assert_eq!(r.birth.segments.len(),3);for(i,(c,w))in PhysicalBirthRule::Gauss2.nodes().iter().enumerate(){let birth=&r.birth.births[i];assert_eq!(birth.a,b.a*(*c*dx).exp());assert!(birth.proper_time_weight_s>0.);let expected=d.source.at_redshift(1./birth.a-1.).unwrap().per_h_s*dx*w/d.geometry_point(birth.a).unwrap().h_flrw_per_s;assert!((birth.added_photons_per_h-expected).abs()<1e-12*expected);}
 for j in 0..3{let actual=r.birth.segments.iter().map(|v|v.photo_events_per_h[j]).sum::<f64>();assert!((actual-s.ledgers.photo_events[j]).abs()<1e-16);}assert!(r.birth.segments.iter().all(|v|v.dt_s>0.));let(n,e)=d.residuals(&s).unwrap();assert!(n.abs()<1e-12&&e.abs()<1e-10);}
#[test]fn source_disabled_retains_seed_accountability_and_no_new_emission(){let(d,mut s,_)=initial(true);let b=s.clone();let r=d.fixed_step_physical_birth_ssprk2(&mut s,1e-5/32.,PhysicalBirthRule::DisabledGauss2).unwrap();assert_eq!(s.ledgers.source_n,b.ledgers.source_n);assert_eq!(s.ledgers.source_u,b.ledgers.source_u);assert!(r.birth.births.iter().all(|b|b.added_photons_per_h==0.));assert!(s.ledgers.absorbed_n>0.);let(n,e)=d.residuals(&s).unwrap();assert!(n.abs()<1e-12&&e.abs()<1e-10);}
#[test]fn scalar_attenuation_is_ignored_only_by_named_ssprk_api(){let(mut d,mut a,k)=initial(true);let(_,mut b,_)=initial(true);let mut n=0;d.chemical_stage_ssprk2(&mut a,0.01/k,&mut n).unwrap();d.set_source_clocks(&b,SourceClockConfig{attenuation:PhotonAttenuation::BackwardEuler,..options()}).unwrap();let mut m=0;d.chemical_stage_ssprk2(&mut b,0.01/k,&mut m).unwrap();same(&a,&b);let p=PhotonState{number:b.photons.clone(),energy_ref:b.photon_energy_ref.clone(),support_lo:b.photon_support_lo.clone(),support_hi:b.photon_support_hi.clone()};d.transport.validate_state(&p).unwrap();}
